import json
from pathlib import Path
p=Path(__file__).resolve().parent
r=json.loads((p/'results.json').read_text())
data=dict(F=float(r['F']),V=float(r['V']),row=r['rows'][0])
html='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{font-family:var(--font-sans,system-ui);color:var(--foreground,#20232b);margin:0}p{line-height:1.5;margin:8px 0 16px}.note{font-size:13px;color:var(--muted-foreground,#666)}.controls{display:flex;gap:20px;flex-wrap:wrap;margin:18px 0}label{flex:1;min-width:220px;font-size:14px}input{width:100%;accent-color:#3a8d87}.stats{display:flex;gap:10px;flex-wrap:wrap}.stat{flex:1;min-width:140px;background:var(--secondary,#f4f6f6);border-radius:var(--radius,8px);padding:16px;font-size:13px}.stat strong{display:block;font-size:23px;margin-top:5px}svg{width:100%;height:300px;overflow:visible}svg text{fill:var(--muted-foreground,#666);font-size:12px}.axis{stroke:var(--border,#bbb)}button{color:inherit;background:var(--secondary,#eee);border:1px solid var(--border,#ccc);padding:6px 12px;border-radius:6px;cursor:pointer}.key{display:flex;gap:18px;flex-wrap:wrap;font-size:13px}.teal{color:#398c85}.orange{color:#bd8427}
</style></head><body>
<p><b>How the spending window opens and closes</b><br>One hypothetical replay of the largest pool by stake in M2’s October 9 snapshot. Move the controls to see how token value and execution cost change its incentive.</p>
<div class="controls"><label>Reward valuation: <b id="valLabel"></b> of baseline<input aria-label="Reward valuation multiplier" id="valuation" type="range" min="0.1" max="1.5" value="1" step="0.05"></label><label>Execution cost per $1 invoice: <b id="costLabel"></b><input aria-label="Execution cost per dollar invoiced" id="cost" type="range" min="0" max="2" value="0.3" step="0.05"></label></div>
<div class="stats"><div class="stat">Best spending point<strong id="opt"></strong></div><div class="stat">Largest modeled net gain<strong id="gain"></strong></div><div class="stat">Total gain falls to zero<strong id="end"></strong></div></div>
<svg id="chart" viewBox="0 0 700 300" role="img" aria-label="Incremental net value versus gross self-funded invoices"></svg>
<div class="key"><span class="teal">● Positive total value</span><span class="orange">┆ Reward stops growing at the stake cap</span></div>
<p id="explain"></p><button id="reset">Reset assumptions</button>
<p class="note">Gross invoices are spending on real work paid to the pool itself. Net value includes retained, unsold LPT valued at $1.71765 × the selected multiplier. The stake cap is fixed at $111.24 of added invoices in this replay. Native commissions and operator-address ownership proxy; full unchanged score; illustrative 94% node allowance and 50/50 fee split; emission base calibrated from round 4364 at hypothetical launch r=0. Other pools are fixed. No setup cost, financing, cash limit, capacity limit or price impact. This is an economic illustration, not observed conduct or a live network estimate.</p>
<script>const D=__DATA__;const $=id=>document.getElementById(id);const f=D.F,v=D.V,a=+D.row.fee_share,s=+D.row.stake_share,t=+D.row.reward_retention,z=+D.row.node_fee_retention,cap=+D.row.cap_invoice_usdc;const money=n=>'$'+n.toFixed(2);
function calculate(mult,cost){const l=1-.5*z+cost,V=v*mult,star=Math.max(0,Math.min(cap,Math.sqrt(V*t*f*(1-a)/l)-f)),profit=x=>V*t*(Math.min((a*f+x)/(f+x),s)-a)-l*x,peak=profit(star);let root=0;if(peak>1e-10){let u=V*t*(1-a)/l-f;root=u<=cap?u:V*t*(s-a)/l}return{l,star,profit,peak,root}}
function draw(){let mult=+$('valuation').value,cost=+$('cost').value,o=calculate(mult,cost);$('valLabel').textContent=mult.toFixed(2)+'×';$('costLabel').textContent=money(cost);$('opt').textContent=money(o.star);$('gain').textContent=money(Math.max(0,o.peak));$('end').textContent=o.root?money(o.root):'No window';let width=Math.max(320,$('chart').clientWidth);$('chart').setAttribute('viewBox',`0 0 ${width} 300`);let xmax=Math.max(cap*1.25,o.root*1.18,150),ymin=Math.min(-20,o.profit(xmax)),ymax=Math.max(20,o.peak*1.25),X=x=>48+(width-64)*x/xmax,Y=y=>250-215*(y-ymin)/(ymax-ymin),svg='';
for(let j=0;j<=4;j++){let x=xmax*j/4,y=ymin+(ymax-ymin)*j/4;svg+=`<line class="axis" x1="48" y1="${Y(y)}" x2="${width-16}" y2="${Y(y)}" opacity=".4"/><text x="41" y="${Y(y)+4}" text-anchor="end">${Math.round(y)}</text><text x="${X(x)}" y="272" text-anchor="middle">${Math.round(x)}</text>`}
svg+=`<line class="axis" x1="48" y1="${Y(0)}" x2="${width-16}" y2="${Y(0)}"/><text x="48" y="18">Net value ($ equivalent)</text><text x="${width/2}" y="296" text-anchor="middle">Gross self-funded invoices ($)</text>`;
if(o.root){let pts=Array.from({length:181},(_,i)=>{let x=o.root*i/180;return`${X(x)},${Y(o.profit(x))}`});svg+=`<path d="M${X(0)},${Y(0)} L${pts.join(' L')} Z" fill="#398c85" opacity=".15"/>`}
const xs=[...Array.from({length:301},(_,i)=>xmax*i/300),cap,o.star,o.root].filter(x=>x>=0&&x<=xmax).sort((a,b)=>a-b);svg+=`<path d="M${xs.map(x=>`${X(x)},${Y(o.profit(x))}`).join(' L')}" stroke="#398c85" stroke-width="3" fill="none"/><line x1="${X(cap)}" x2="${X(cap)}" y1="30" y2="250" stroke="#bd8427" stroke-dasharray="5 5"/>`;
if(o.peak>0)svg+=`<circle cx="${X(o.star)}" cy="${Y(o.peak)}" r="5" fill="#398c85"/><text x="${Math.min(width-90,X(o.star)+8)}" y="${Y(o.peak)-10}">Best point</text>`;
$('chart').innerHTML=svg;$('explain').textContent=o.root?`Total value stays positive until ${money(o.root)}, but a profit-seeking operator stops at ${money(o.star)}: spending more after that reduces its gain. The shaded region is the total-profit window; the best point is the rational stopping point under these assumptions.`:'Even with unused stake headroom, retained additional rewards do not cover the added costs. Zero spending is the best choice under these assumptions.';
}
window.addEventListener('resize',draw);$('valuation').oninput=draw;$('cost').oninput=draw;$('reset').onclick=()=>{$('valuation').value=1;$('cost').value=.3;draw()};const check=calculate(1,.3);console.assert(Math.abs(check.peak-102.16816349473)<1e-8,'Baseline peak agrees with Decimal accounting');console.assert(Math.abs(check.root-208.08621111416)<1e-8,'Break-even agrees with Decimal accounting');console.assert(calculate(.1,.3).peak===0,'Low valuation closes window');draw();console.log('PASS: baseline peak, break-even and closed-window controls');
</script></body></html>'''.replace('__DATA__',json.dumps(data))
(p/'window.html').write_text(html)
print(p/'window.html')
